const nName = "Humayra Siddika";
const nEmail = "humayra@gmail.com";
const nCompanyName = "Ostad";

const newName = `${nName} ; Update ${Date.now()}`;
const newEmail = `${nEmail} ; Update ${Date.now()}`;
const newCompanyName = `${nCompanyName} ; Update ${Date.now()}`;

pm.environment.set("updated_User_name", newName);
pm.environment.set("updated_User_email", newEmail);
pm.environment.set("updated_User_company_name", newCompanyName);

const response = pm.response.json();

pm.test("1. Returned ID should be the same as stored ID",function (){
pm.expect(response.id).to.eql(parseInt(pm.environment.get("User_id")));
});

// The request body updates only name, email and company name, 
// Issue: PUT response does not contain the "phone" field, so the phone validation cannot be performed.
pm.test("2. Response phone number should not be empty", () => {
pm.expect(response.phone).to.not.be.empty;
});

pm.test("3. Returned name should match the updated name",function (){
pm.expect(response.name).to.eql(pm.environment.get("updated_User_name"));
});

